// src/components/teacher/TeacherDashboard.jsx
import React from 'react';
import { Box, Paper, Typography, Button } from '@mui/material';
import { Link } from 'react-router-dom';

const TeacherDashboard = () => {
  return (
    <Box sx={{ width: '100%', p: 3 }}>
      <Paper elevation={3} sx={{ p: 4 }}>
        <Typography variant="h5" gutterBottom>
          Teacher Dashboard
        </Typography>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          <Button variant="contained" component={Link} to="/teacher/schedule">
            View Schedule
          </Button>
          <Button variant="contained" component={Link} to="/teacher/attendance/self">
            Self Attendance
          </Button>
          <Button variant="contained" component={Link} to="/teacher/attendance/student">
            Student Attendance
          </Button>
          <Button variant="contained" component={Link} to="/teacher/grading">
            Provide Marks and Grades
          </Button>
          <Button variant="contained" component={Link} to="/teacher/reports">
            Generate Reports
          </Button>
          <Button variant="contained" component={Link} to="/teacher/settings/general">
            General Settings
          </Button>
        </Box>
      </Paper>
    </Box>
  );
};

export default TeacherDashboard;