// src/components/parent/Messages.jsx
import React, { useState, useEffect } from 'react';
import { Box, Typography, CircularProgress, Snackbar, Alert, List, ListItem, ListItemText, Paper } from '@mui/material';

const Messages = () => {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [alert, setAlert] = useState(null);

  useEffect(() => {
    fetchMessages();
  }, []);

  const fetchMessages = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/parent/messages');
      const data = await response.json();
      setMessages(data);
    } catch (error) {
      setAlert('Error fetching messages');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box>
      <Typography variant="h6" gutterBottom>
        Messages
      </Typography>
      {loading ? (
        <CircularProgress />
      ) : messages.length ? (
        <Paper>
          <List>
            {messages.map((message) => (
              <ListItem key={message.id}>
                <ListItemText
                  primary={message.title}
                  secondary={message.content}
                />
              </ListItem>
            ))}
          </List>
        </Paper>
      ) : (
        <Typography variant="body1">No messages available</Typography>
      )}
      {alert && (
        <Snackbar open={!!alert} autoHideDuration={6000} onClose={() => setAlert(null)}>
          <Alert onClose={() => setAlert(null)} severity="error">
            {alert}
          </Alert>
        </Snackbar>
      )}
    </Box>
  );
};

export default Messages;