// src/components/parent/StudentProgress.jsx
import React, { useState, useEffect } from 'react';
import { Box, Typography, CircularProgress, Snackbar, Alert } from '@mui/material';

const StudentProgress = () => {
  const [progress, setProgress] = useState(null);
  const [loading, setLoading] = useState(false);
  const [alert, setAlert] = useState(null);

  useEffect(() => {
    fetchStudentProgress();
  }, []);

  const fetchStudentProgress = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/parent/studentProgress');
      const data = await response.json();
      setProgress(data);
    } catch (error) {
      setAlert('Error fetching student progress');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box>
      <Typography variant="h6" gutterBottom>
        Student Progress
      </Typography>
      {loading ? (
        <CircularProgress />
      ) : progress ? (
        <Typography variant="body1">{progress.details}</Typography>
      ) : (
        <Typography variant="body1">No progress data available</Typography>
      )}
      {alert && (
        <Snackbar open={!!alert} autoHideDuration={6000} onClose={() => setAlert(null)}>
          <Alert onClose={() => setAlert(null)} severity="error">
            {alert}
          </Alert>
        </Snackbar>
      )}
    </Box>
  );
};

export default StudentProgress;