// src/components/parent/FeesDetails.jsx
import React, { useState, useEffect } from 'react';
import { Box, Typography, CircularProgress, Snackbar, Alert, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper } from '@mui/material';

const FeesDetails = () => {
  const [feesDetails, setFeesDetails] = useState([]);
  const [loading, setLoading] = useState(false);
  const [alert, setAlert] = useState(null);

  useEffect(() => {
    fetchFeesDetails();
  }, []);

  const fetchFeesDetails = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/parent/feesDetails');
      const data = await response.json();
      setFeesDetails(data);
    } catch (error) {
      setAlert('Error fetching fees details');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box>
      <Typography variant="h6" gutterBottom>
        Fees Details
      </Typography>
      {loading ? (
        <CircularProgress />
      ) : feesDetails.length ? (
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Date</TableCell>
                <TableCell>Description</TableCell>
                <TableCell>Amount</TableCell>
                <TableCell>Status</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {feesDetails.map((fee) => (
                <TableRow key={fee.id}>
                  <TableCell>{new Date(fee.date).toLocaleDateString()}</TableCell>
                  <TableCell>{fee.description}</TableCell>
                  <TableCell>{fee.amount}</TableCell>
                  <TableCell>{fee.status}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      ) : (
        <Typography variant="body1">No fees details available</Typography>
      )}
      {alert && (
        <Snackbar open={!!alert} autoHideDuration={6000} onClose={() => setAlert(null)}>
          <Alert onClose={() => setAlert(null)} severity="error">
            {alert}
          </Alert>
        </Snackbar>
      )}
    </Box>
  );
};

export default FeesDetails;